Implementation:
```
IF NOT Mode THEN
    phase := E_Phase.WAIT_FEED;
    kick := FALSE;
    CompletionLight := FALSE;
    MotorForward := ForwardButton AND NOT ReverseButton;
    MotorReverse := ReverseButton AND NOT ForwardButton;
    prevMode := FALSE;
ELSE
    IF NOT prevMode THEN
        phase := E_Phase.WAIT_FEED;
        kick := FALSE;
        CompletionLight := FALSE;
        MotorForward := FALSE;
        MotorReverse := FALSE;
    END_IF;
    prevMode := TRUE;

    MotorForward := FALSE;
    MotorReverse := FALSE;

    CASE phase OF
        E_Phase.WAIT_FEED:
            kick := FALSE;
            CompletionLight := FALSE;
            IF SensorFeed THEN
                MotorForward := TRUE;
                phase := E_Phase.MOVE_TO_WASH;
            END_IF;

        E_Phase.MOVE_TO_WASH:
            IF SensorWash THEN
                MotorForward := FALSE;
                phase := E_Phase.WAIT_WASH;
            ELSE
                MotorForward := TRUE;
            END_IF;

        E_Phase.WAIT_WASH:
            IF SensorWash AND washComplete THEN
                MotorForward := TRUE;
                phase := E_Phase.MOVE_TO_WEIGHT;
            END_IF;

        E_Phase.MOVE_TO_WEIGHT:
            IF SensorWeight THEN
                MotorForward := FALSE;
                phase := E_Phase.WAIT_WEIGHT;
            ELSE
                MotorForward := TRUE;
            END_IF;

        E_Phase.WAIT_WEIGHT:
            kick := FALSE;
            IF SensorWeight AND weightComplete THEN
                IF (weight >= 100.0 - 0.00001) AND (weight <= 200.0 + 0.00001) THEN
                    firingTemp := 500.0 + (weight - 100.0) * 0.5;
                    kick := FALSE;
                    MotorForward := TRUE;
                    phase := E_Phase.MOVE_TO_FIRING;
                ELSE
                    kick := TRUE;
                    MotorForward := FALSE;
                    phase := E_Phase.REJECTED;
                END_IF;
            END_IF;

        E_Phase.MOVE_TO_FIRING:
            IF SensorFiring THEN
                MotorForward := FALSE;
                phase := E_Phase.WAIT_FIRING;
            ELSE
                MotorForward := TRUE;
            END_IF;

        E_Phase.WAIT_FIRING:
            IF SensorFiring AND firingComplete THEN
                MotorForward := TRUE;
                phase := E_Phase.MOVE_TO_OUTPUT;
            END_IF;

        E_Phase.MOVE_TO_OUTPUT:
            IF SensorOutput THEN
                MotorForward := FALSE;
                CompletionLight := TRUE;
                phase := E_Phase.OUTPUT_DONE;
            ELSE
                MotorForward := TRUE;
            END_IF;

        E_Phase.OUTPUT_DONE:
            IF SensorOutput THEN
                MotorForward := FALSE;
                CompletionLight := TRUE;
            ELSE
                CompletionLight := FALSE;
                phase := E_Phase.WAIT_FEED;
            END_IF;

        E_Phase.REJECTED:
            IF NOT SensorWeight THEN
                kick := FALSE;
                phase := E_Phase.WAIT_FEED;
            ELSE
                kick := TRUE;
                MotorForward := FALSE;
            END_IF;
    END_CASE;
END_IF;
```
